import { createHash } from 'node:crypto'
import { MessageBuilder, type Secret } from '@poppinss/utils'
import { RuntimeException } from '@poppinss/utils/exception'
import { base64UrlEncode, base64UrlDecode } from './base64.ts'
import { Hmac } from './hmac.ts'
import * as errors from './exceptions.ts'

/**
 * Message verifier is similar to the encryption. However, the actual payload
 * is not encrypted and just base64 encoded. This is helpful when you are
 * not concerned about the confidentiality of the data, but just want to
 * make sure that is not tampered with after encoding.
 */
export class MessageVerifier {
  /**
   * The keys for signing and verifying values. They are derived
   * from the user provided secrets.
   */
  #cryptoKeys: Buffer[]

  /**
   * Use `dot` as a separator for joining encrypted value, iv and the
   * hmac hash. The idea is borrowed from JWT's in which each part
   * of the payload is concatenated with a dot.
   */
  #separator = '.'

  constructor(secrets: (string | Secret<string>)[]) {
    if (secrets.length === 0) {
      throw new errors.E_MISSING_ENCRYPTER_KEYS()
    }

    this.#cryptoKeys = secrets.map((secret) => {
      const revealedSecret = typeof secret === 'string' ? secret : secret.release()

      if (!revealedSecret) {
        throw new errors.E_MISSING_ENCRYPTER_KEY()
      }

      if (revealedSecret.length < 16) {
        throw new errors.E_INSECURE_ENCRYPTER_KEY()
      }

      return createHash('sha256').update(revealedSecret).digest()
    })
  }

  /**
   * Sign a given piece of value using the app secret. A wide range of
   * data types are supported.
   *
   * - String
   * - Arrays
   * - Objects
   * - Booleans
   * - Numbers
   * - Dates
   *
   * You can optionally define a purpose for which the value was signed and
   * mentioning a different purpose/no purpose during unsign will fail.
   */
  sign(payload: any, expiresIn?: string | number, purpose?: string) {
    if (payload === null || payload === undefined) {
      throw new RuntimeException(`Cannot sign "${payload}" value`)
    }

    const encoded = base64UrlEncode(new MessageBuilder().build(payload, expiresIn, purpose))
    return `${encoded}${this.#separator}${new Hmac(this.#cryptoKeys[0]).generate(encoded)}`
  }

  /**
   * Unsign a previously signed value with an optional purpose
   */
  unsign<T extends any>(payload: string, purpose?: string): T | null {
    if (typeof payload !== 'string') {
      return null
    }

    /**
     * Ensure value is in correct format
     */
    const parts = payload.split(this.#separator)
    if (parts.length !== 2) {
      return null
    }

    const [encoded, hash] = parts
    if (!encoded || !hash) {
      return null
    }

    /**
     * Ensure value can be decoded
     */
    const decoded = base64UrlDecode(encoded, 'utf8')
    if (!decoded) {
      return null
    }

    for (const cryptoKey of this.#cryptoKeys) {
      const isValid = new Hmac(cryptoKey).compare(encoded, hash)
      if (isValid) {
        return new MessageBuilder().verify(decoded, purpose)
      }
    }

    return null
  }
}
